<script lang="ts">
  import { Check, ChevronDown, Clock3, Coins, Crown, Sparkles, Ticket, TriangleAlert, Zap } from '@lucide/svelte';
  import GameButton from './GameButton.svelte';
  import RewardIcon from './RewardIcon.svelte';
  import PassArtwork from './PassArtwork.svelte';
  import { passBenefitMilestones, vipOffer } from '../services/passService';
  import { PASS_RULES } from '../services/battlePassService';
  import { currentSeason, hasPassAccess } from '../services/demoService';
  import type { PlayerState } from '../types';
  let { player, packageId, now, onSelect, onConfirm, onTopUp, onClose }: {
    player: PlayerState; packageId: string; now: number;
    onSelect: (id: string) => void; onConfirm: () => void; onTopUp: () => void; onClose: () => void;
  } = $props();
  let offer = $derived(vipOffer(player, packageId, now));
  let plans = $derived(player.demo.config.vipPlans.filter((plan) => !offer?.active || (plan.startLevel ?? 1) === 1));
  let basePlanCost = $derived(player.demo.config.vipPlans.find((plan) => (plan.startLevel ?? 1) === 1)?.cost ?? 0);
  let milestones = $derived(passBenefitMilestones(player, now));
  let levelThirty = $derived(milestones.find((item) => item.level === 30));
  let season = $derived(currentSeason(player, now));
  let existingTrack = $derived(!offer?.active && hasPassAccess(player, now));
  let short = $derived(Math.max(0, (offer?.plan.cost ?? 0) - player.masquePoints));
  let pending = $derived(offer && (!existingTrack || offer.boosted) ? season.premium.slice(0, Math.min(50, offer.levelAfter)).map((reward, index) => ({ reward, index })).filter((item) => !player.demo.passes[season.id]?.claims.includes(`premium-${item.index}`)) : []);
  let pendingEnergy = $derived(pending.filter((item) => item.reward.type === 'energy').reduce((total, item) => total + (item.reward.amount ?? 0), 0));
  let pendingPoints = $derived(pending.filter((item) => item.reward.type === 'points').reduce((total, item) => total + (item.reward.amount ?? 0), 0));
  let pendingTickets = $derived(pending.filter((item) => item.reward.type === 'ticket').reduce((total, item) => total + (item.reward.amount ?? 0), 0));
  let highlights = $derived(pending.filter((item) => ['avatar', 'pet', 'wing', 'frame', 'background'].includes(item.reward.type)).slice(-4));
</script>

{#if offer}
  <section class="space-y-4 text-left text-[#344b67]" data-testid="vip-pass-offer">
    <header class="relative isolate min-h-28 overflow-hidden border-b border-sky-100 bg-sky-50/80 px-1 pt-2 pb-4 pr-20">
      <span class="absolute top-0 right-0 -z-10 h-24 w-24"><PassArtwork kind="crest" /></span>
      <p class="flex items-center gap-1 text-[9px] font-bold text-sky-600"><Sparkles size={12} />MASQUE VIP PASS</p><h2 class="mt-1 text-[22px] font-bold leading-tight text-[#3d397c]">{offer.active ? 'VIP Pass ใช้งานอยู่' : 'เลือก VIP Pass'}</h2><p class="mt-2 text-[10px] leading-relaxed text-[#7d8aa4]">{offer.active && player.vipExpiresAt ? `ใช้ได้ถึง ${new Date(player.vipExpiresAt).toLocaleDateString('th-TH')} · ซื้อแพ็กใหม่ได้เมื่อหมดอายุ` : 'เลือกแพ็กเริ่มต้นหรือข้ามเลเวล · ใช้ได้ 30 วัน'}</p>
    </header>
    {#if !offer.active}<div class="grid grid-cols-2 gap-3 pt-1" role="radiogroup" aria-label="เลือกแพ็ก VIP Pass">{#each plans as plan (plan.id)}{@const candidate = vipOffer(player, plan.id, now)}{#if candidate}<button class={['relative flex min-h-52 min-w-0 flex-col items-center rounded-lg border-2 px-2 pt-3 pb-2 text-center transition-[transform,border-color,box-shadow] duration-150 active:translate-y-0.5 disabled:opacity-40 motion-reduce:transition-none', plan.id === packageId ? 'border-amber-400 bg-[#fffae9] shadow-[0_4px_0_#edc56b,0_8px_15px_#b48e3d25]' : 'border-[#deebf5] bg-[#f7fbff] shadow-[0_3px_0_#d9e3f0]']} role="radio" aria-checked={plan.id === packageId} aria-label={candidate.boosted ? `VIP Pass LV.${plan.startLevel}` : 'VIP Pass ปกติ'} disabled={!candidate.eligible} onclick={() => onSelect(plan.id)}>
      <span class={['absolute -top-2.5 inset-x-1 mx-auto w-fit rounded-md border border-white px-2 py-1 text-[8px] font-bold text-white', candidate.boosted ? 'bg-[#ed9c61]' : 'bg-[#63afd1]']}>{candidate.boosted ? `LV.${plan.startLevel} BOOST · +${Math.max(0, candidate.levelAfter - candidate.level)} LV` : 'VIP PASS · LV.1'}</span>
      <span class="block h-24 w-full"><PassArtwork kind={candidate.boosted ? 'boost' : 'standard'} /></span><strong class="text-sm font-bold text-[#3d397c]">{candidate.boosted ? `เริ่ม LV.${plan.startLevel}` : 'แพ็กเริ่มต้น LV.1'}</strong><span class="mt-1 min-h-7 text-[9px] leading-relaxed text-[#8795a8]">{candidate.boosted ? `เพิ่มทันที +${Math.max(0, candidate.levelAfter - candidate.level)} LV · +${(Math.max(0, candidate.levelAfter - candidate.level) * PASS_RULES.xpPerLevel).toLocaleString()} XP · จ่ายเพิ่ม ${(Math.max(0, plan.cost - basePlanCost)).toLocaleString()} MP จาก LV.1` : `ไม่ลดเลเวลเดิม · ${PASS_RULES.days} วัน`}</span><span class="mt-auto flex w-full items-center justify-between border-t border-white pt-2"><strong class="text-sm tabular-nums text-[#7454ab]">{plan.cost.toLocaleString()} MP</strong><span class={['grid size-5 place-items-center rounded-full border', plan.id === packageId ? 'border-amber-400 bg-amber-400 text-white' : 'border-[#cfdaea] bg-white']}>{#if plan.id === packageId}<Check size={13} strokeWidth={3} />{/if}</span></span>{#if !candidate.eligible}<small class="mt-1 text-[9px] text-rose-500">เลเวลถึงเป้าแล้ว</small>{/if}</button>{/if}{/each}</div>{/if}
    <div class="grid grid-cols-3 gap-2 border-y border-[#e5ebf2] py-3 text-center"><div><Clock3 size={15} class="mx-auto mb-1 text-sky-500" /><strong class="block text-sm">{offer.plan.durationDays} วัน</strong><small class="text-[8px] text-[#8795a8]">สิทธิ์ VIP</small></div><div><Zap size={15} class="mx-auto mb-1 text-amber-500" /><strong class="block text-sm">{player.demo.config.energyMax + player.demo.config.vipEnergyBonus}</strong><small class="text-[8px] text-[#8795a8]">MAX · +{player.demo.config.vipEnergyBonus}</small></div><div><Crown size={15} class="mx-auto mb-1 text-[#a58bda]" /><strong class="block text-sm">LV.{offer.levelAfter}</strong><small class="text-[8px] text-[#8795a8]">VIP Pass</small></div></div>
    <div class="space-y-2 text-[11px]"><p class="flex items-center gap-2"><Check size={15} class="shrink-0 text-sky-600" />{player.demo.config.vipFreeEntry ? 'เกมทั่วไปเข้าได้โดยไม่หัก Energy · Ranked ใช้บัตรตามปกติ' : 'สิทธิ์เข้าเกมตามกติกาปกติ'}</p><p class="flex items-center gap-2"><Zap size={15} class="shrink-0 text-amber-500" />MAX Energy เพิ่ม {player.demo.config.vipEnergyBonus} · ฟื้น +1 ทุก {player.demo.config.regenMinutes} นาที</p><p class="flex items-center gap-2"><Crown size={15} class="shrink-0 text-[#a58bda]" />รับของจาก VIP Pass ตาม XP ในซีซัน</p><p class="flex items-center gap-2"><Ticket size={15} class="shrink-0 text-rose-400" />คูปองสุ่มตอนซื้อ: {offer.plan.bonusTickets ?? 0} ใบ</p><p class="flex items-center gap-2"><Clock3 size={15} class="shrink-0 text-sky-600" />ใช้ได้ถึง {new Date(offer.expiresAt).toLocaleDateString('th-TH')}</p><p class="text-[9px] leading-relaxed text-[#8795a8]">VIP ข้ามซีซันได้ · เลเวล Pass เริ่มใหม่ตามซีซัน · รางวัลที่ปลดล็อกกดรับในหน้า Pass</p></div>
    {#if existingTrack}<p class="border-y border-sky-100 bg-sky-50 px-2 py-3 text-[11px] leading-relaxed text-sky-800">คุณมีสิทธิ์ช่องรางวัล VIP ซีซันนี้จากแพ็กเดิมแล้ว การซื้อนี้เพิ่มวัน VIP และสิทธิ์เข้าเกม</p>{:else if !offer.active && !offer.boosted && levelThirty}<p class="border-y border-sky-100 bg-sky-50 px-2 py-3 text-[11px] leading-relaxed text-sky-800">เมื่อเล่นถึง LV.30 รับจากช่อง VIP เพิ่มอีก <strong>{levelThirty.vipEnergy} Energy</strong>, {levelThirty.vipPoints.toLocaleString()} MP และตั๋วกาชา {levelThirty.vipTickets} ใบ</p>{/if}
    {#if !offer.active && pending.length > 0}<section class="space-y-2 border-y border-amber-100 bg-[#fffaf0] px-2 py-3" aria-label="รางวัลที่ปลดล็อกหลังซื้อ"><h3 class="text-xs font-bold">ปลดล็อก {pending.length} ขั้น VIP ให้กดรับ</h3><div class="flex flex-wrap gap-x-4 gap-y-1 text-[11px]"><span class="flex items-center gap-1"><Zap size={14} class="text-sky-600" />{pendingEnergy} Energy</span><span class="flex items-center gap-1"><Coins size={14} class="text-amber-500" />{pendingPoints.toLocaleString()} MP</span><span class="flex items-center gap-1"><Ticket size={14} class="text-rose-400" />ตั๋วกาชา {pendingTickets}</span></div>{#if highlights.length}<div class="grid grid-cols-4 gap-2 pt-1">{#each highlights as item (item.index)}<div class="grid min-w-0 justify-items-center gap-1"><RewardIcon type={item.reward.type} itemId={item.reward.itemId} size={40} /><small class="line-clamp-2 text-center text-[8px]">{item.reward.title}</small></div>{/each}</div>{/if}<p class="text-[9px] leading-relaxed text-[#9b8c6b]">ต้องกดรับในหน้า Pass · ของซ้ำชดเชยตามกติกา · ไม่เติมพลังทั้งหมดทันที</p></section>{/if}
    {#if !offer.active}<details class="border-b border-[#e5ebf2] pb-3"><summary class="flex min-h-10 cursor-pointer items-center justify-between text-xs font-semibold">รางวัล Energy ตามเลเวล<ChevronDown size={15} /></summary><table class="w-full text-center text-[10px]"><thead class="text-[#8795a8]"><tr><th class="py-2 font-normal">ถึง LV.</th><th class="font-normal">ฟรีสะสม</th><th class="font-normal">VIP เพิ่มอีก</th></tr></thead><tbody>{#each milestones as row (row.level)}<tr class="border-t border-[#edf0f5]"><th class="py-2 font-semibold">{row.level}</th><td>{row.freeEnergy}</td><td class="font-semibold text-amber-700">+{row.vipEnergy}</td></tr>{/each}</tbody></table><p class="mt-2 text-[9px] text-[#8795a8]">ยอดรวมตามตารางซีซัน ไม่ใช่ของแถมทันที · เลเวลเร่งใช้เฉพาะซีซันนี้</p></details>{/if}
    <footer class="sticky bottom-0 space-y-2 border-t-2 border-white bg-[#fcfbff]/95 pt-3 pb-1 backdrop-blur-md">
      {#if offer.active}
        <p class="text-center text-xs font-semibold text-[#6b8795]">VIP Pass ใช้งานถึง {new Date(offer.expiresAt).toLocaleDateString('th-TH')} · เลือกซื้อแพ็กใหม่ได้เมื่อหมดอายุ</p>
        <GameButton block variant="ghost" onclick={onClose}>ปิด</GameButton>
      {:else}
        <div class="flex items-end justify-between gap-2"><strong class="flex items-center gap-1 text-lg tabular-nums text-[#73519b]"><Coins size={16} class="text-amber-500" />{offer.plan.cost.toLocaleString()} <span class="text-[10px]">MP</span></strong><span class="text-right text-[9px] tabular-nums text-[#8795a8]">ยอดของคุณ {player.masquePoints.toLocaleString()} MP</span></div>{#if short > 0}<p class="flex items-center gap-1 text-[10px] text-rose-500" role="status"><TriangleAlert size={13} />ขาดอีก {short.toLocaleString()} MP</p>{/if}<div class="grid grid-cols-[60px_minmax(0,1fr)] items-center gap-2"><button class="min-h-11 rounded-md border border-[#dce5f0] bg-white text-[10px] text-[#8795a8]" onclick={onClose}>ยกเลิก</button><GameButton block variant="gold" label={`ซื้อ VIP Pass LV.${offer.plan.startLevel ?? 1} · ${offer.plan.cost.toLocaleString()} MP`} disabled={short > 0 || !offer.eligible} onclick={onConfirm}><Crown size={15} />ซื้อแพ็ก LV.{offer.plan.startLevel ?? 1}</GameButton></div>{#if short > 0}<button class="min-h-8 w-full text-center text-[10px] font-semibold text-sky-700 underline" onclick={onTopUp}>เติม Masque Points</button>{/if}
      {/if}
    </footer>
  </section>
{/if}